import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import FieldSet from 'flarum/common/components/FieldSet';
import TourSettings from './components/TourSettings';
export default function addTourSettings() {
  // By path: SettingsPage is an async chunk, so importing it here is undefined at boot.
  extend('flarum/forum/components/SettingsPage', 'settingsItems', function (items) {
    if (!app.forum.attribute('datlechin-simple-tour-guide.showInSettings')) return;
    items.add('tourGuide', m(FieldSet, {
      className: "Settings-tourGuide FieldSet--min",
      label: app.translator.trans('datlechin-simple-tour-guide.forum.settings.heading')
    }, m(TourSettings, null)), -10);
  });
}