import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import loadTours from '../loadTours';
import { leadTo, requestTour, startRequested } from '../pendingTour';
export default class TourSettings extends Component {
  loading = true;
  tours = [];
  oninit(vnode) {
    super.oninit(vnode);
    loadTours().then(tours => {
      this.tours = tours;
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    if (this.loading) return m(LoadingIndicator, {
      display: "inline",
      size: "small"
    });
    if (!this.tours.length) {
      return m("div", {
        className: "helpText"
      }, app.translator.trans('datlechin-simple-tour-guide.forum.settings.none'));
    }
    return m("ul", {
      className: "TourSettingsList"
    }, this.tours.map(tour => m("li", {
      className: "TourSettingsList-item"
    }, m("span", {
      className: "TourSettingsList-title"
    }, tour.title()), m(Button, {
      className: "Button Button--link",
      onclick: () => this.take(tour)
    }, tour.completion() ? app.translator.trans('datlechin-simple-tour-guide.forum.settings.take_again') : app.translator.trans('datlechin-simple-tour-guide.forum.settings.take')))));
  }
  take(tour) {
    const waiting = app.translator.trans('datlechin-simple-tour-guide.forum.go_to_page', {
      title: tour.title()
    });
    if (leadTo(tour.route(), waiting)) {
      startRequested(tour);
    } else {
      requestTour(tour.key());
    }
  }
}
flarum.reg.add('datlechin-simple-tour-guide', 'forum/components/TourSettings', TourSettings);