import Model from 'flarum/common/Model';
export default class Tour extends Model {
  key() {
    return Model.attribute('key').call(this);
  }
  title() {
    return Model.attribute('title').call(this);
  }
  isEnabled() {
    return Model.attribute('isEnabled').call(this);
  }
  startMode() {
    return Model.attribute('startMode').call(this);
  }
  route() {
    return Model.attribute('route').call(this);
  }
  devices() {
    return Model.attribute('devices').call(this);
  }
  maxAccountAgeDays() {
    return Model.attribute('maxAccountAgeDays').call(this);
  }
  position() {
    return Model.attribute('position').call(this);
  }
  groups() {
    return Model.hasMany('groups').call(this);
  }

  // From the store rather than the relationship, which misses steps added after the tour loaded.
  steps() {
    return this.store.all('tour-guide-steps').filter(step => step.tour() === this).sort((a, b) => a.position() - b.position());
  }
  enabledSteps() {
    return Model.hasMany('enabledSteps').call(this);
  }
  completion() {
    return Model.hasOne('completion').call(this);
  }
}
flarum.reg.add('datlechin-simple-tour-guide', 'common/models/Tour', Tour);