import app from 'flarum/forum/app';
let cached = null;

// Ended during this visit, so a tour is not offered again before its completion is saved.
let ended = new Set();
function fetchTours(filter) {
  return app.store.find('tour-guide-tours', {
    filter,
    include: 'enabledSteps,completion'
  }, undefined, {
    errorHandler: () => {}
  }).then(tours => [...tours]);
}
export default function loadTours() {
  return cached ??= fetchTours({
    available: '1'
  }).catch(() => {
    cached = null;
    return [];
  });
}

// Disabled tours and tours meant for others included: an admin previewing their own work.
export function loadPreview() {
  return fetchTours({}).catch(() => []);
}
export function forgetTours() {
  cached = null;
  ended = new Set();
}
export function endedThisVisit(tour) {
  return ended.has(tour);
}
export function recordCompletion(tour, outcome, lastStep) {
  ended.add(tour);
  app.store.createRecord('tour-guide-completions').save({
    outcome,
    relationships: {
      tour,
      lastStep
    }
  }, {
    errorHandler: () => {}
  }).then(completion => tour.pushData({
    relationships: {
      completion
    }
  })).catch(() => {});
}
export function resetTours(userId) {
  forgetTours();
  return app.request({
    method: 'DELETE',
    url: `${app.forum.attribute('apiUrl')}/users/${userId}/tour-guide-completions`
  });
}